VOCAB_NAMESPACE = uuid.UUID("a1b2c3d4-e5f6-7a8b-9c0d-1e2f3a4b5c6d")

def make_uuid(word_str):
    return str(uuid.uuid5(VOCAB_NAMESPACE, word_str.lower()))

# Helper to build word entry
