assert len(all_words) == 500, f"Expected 500 words, got {len(all_words)}"
assert len(b2_clean) == 175, f"Expected 175 B2, got {len(b2_clean)}"
assert len(c1_clean) == 225, f"Expected 225 C1, got {len(c1_clean)}"
assert len(c2_clean) == 100, f"Expected 100 C2, got {len(c2_clean)}"

# Write JSON output for frontend & backend services
os.makedirs("src/data", exist_ok=True)
json_path = "src/data/vocabulary_500.json"
with open(json_path, "w", encoding="utf-8") as f:
    json.dump(all_words, f, indent=2, ensure_ascii=False)
print(f"Successfully generated {json_path}")

# Write SQL Seed File for Supabase
sql_path = "supabase/seed_vocabulary.sql"
with open(sql_path, "w", encoding="utf-8") as f:
    f.write("-- ==============================================================================\n")
    f.write("-- SAT PREPARATION PLATFORM: 500 CURATED ACADEMIC VOCABULARY WORDS SEED\n")
    f.write("-- CEFR: 175 B2 (35%), 225 C1 (45%), 100 C2 (20%)\n")
    f.write("-- ==============================================================================\n\n")
    f.write("INSERT INTO public.vocabulary_words (\n")
    f.write("    id, word, pronunciation, part_of_speech, cefr_level, definition,\n")
    f.write("    simple_explanation, synonyms, antonyms, example_sentence,\n")
    f.write("    sat_context_sentence, category, tags\n")
    f.write(") VALUES\n")

    val_lines = []
    for w in all_words:
        wid = w["id"]
        word = w["word"].replace("'", "''")
        ipa = w["pronunciation"].replace("'", "''")
        pos = w["part_of_speech"].replace("'", "''")
        lvl = w["cefr_level"]
        defn = w["definition"].replace("'", "''")
        simple = w["simple_explanation"].replace("'", "''")
        
        # Arrays
        def sql_escape(s):
            return s.replace("'", "''")

        syns_items = [f"'{sql_escape(s)}'" for s in w["synonyms"]]
        syns_sql = f"ARRAY[{', '.join(syns_items)}]::TEXT[]" if syns_items else "'{}'::TEXT[]"

        ants_items = [f"'{sql_escape(a)}'" for a in w["antonyms"]]
        ants_sql = f"ARRAY[{', '.join(ants_items)}]::TEXT[]" if ants_items else "'{}'::TEXT[]"

        tags_items = [f"'{sql_escape(t)}'" for t in w["tags"]]
        tags_sql = f"ARRAY[{', '.join(tags_items)}]::TEXT[]" if tags_items else "'{}'::TEXT[]"
        
        ex = sql_escape(w["example_sentence"])
        sat_ex = sql_escape(w["sat_context_sentence"])
        cat = sql_escape(w["category"])
        
        val_lines.append(
            f"('{wid}', '{word}', '{ipa}', '{pos}', '{lvl}', '{defn}', '{simple}', {syns_sql}, {ants_sql}, '{ex}', '{sat_ex}', '{cat}', {tags_sql})"
        )

    f.write(",\n".join(val_lines))
    f.write("\nON CONFLICT (word) DO UPDATE SET\n")
    f.write("    pronunciation = EXCLUDED.pronunciation,\n")
    f.write("    part_of_speech = EXCLUDED.part_of_speech,\n")
    f.write("    cefr_level = EXCLUDED.cefr_level,\n")
    f.write("    definition = EXCLUDED.definition,\n")
    f.write("    simple_explanation = EXCLUDED.simple_explanation,\n")
    f.write("    synonyms = EXCLUDED.synonyms,\n")
    f.write("    antonyms = EXCLUDED.antonyms,\n")
    f.write("    example_sentence = EXCLUDED.example_sentence,\n")
    f.write("    sat_context_sentence = EXCLUDED.sat_context_sentence,\n")
    f.write("    category = EXCLUDED.category,\n")
    f.write("    tags = EXCLUDED.tags,\n")
    f.write("    updated_at = timezone('utc', now());\n")

print(f"Successfully generated {sql_path} with {len(all_words)} words.")
